// ── TIER ALGORITHM ────────────────────────────────────────────────────────────
// COLE decides the tier — the buyer never chooses in the popup
// Rule: $67 only for SAFE/CLEAR outcomes. ANY risk = $147.

function recommendedTier(
  bracketStatus: BracketStatus,
  superType: number | string,
  incomeLevel: number | string,
  contributionStructure: number | string,
  assessmentStatus: number | string,
  primaryConcern: number | string,
): PackTier {
  // A defined benefit interest, an assessment already received, or a payment/deferral concern -> tier2. Otherwise tier1.
    if (superType === "defined_benefit" || superType === "both" || assessmentStatus === "assessment_received" || assessmentStatus === "assessment_deferral" || primaryConcern === "payment_deferral" || primaryConcern === "other_tools") return 147;
  // Default: safe = $67, any risk = $147
  return (bracketStatus === "clear" || bracketStatus === "out_of_scope" || bracketStatus === "pass")
    ? 67
    : 147;
}

